"""SessionFork — 会话分叉/恢复。

借鉴 deepseek-harness 的 Session Fork/Resume：
- 从任意 turn 边界分叉出新会话
- 从持久化恢复继续（崩溃恢复）
- 分叉的会话共享原始事件日志的前缀

用法:
    fork = SessionFork(session_log)
    new_log = fork.at(turn_boundary_seq=42)
    new_log.append(EventType.USER_MESSAGE, {'content': '从分叉继续...'})
"""
import logging
import time
import uuid
from typing import Optional

from .session_log import SessionLog, SessionEvent, EventType

logger = logging.getLogger("agent.session_fork")


class SessionFork:
    """会话分叉器。

    从原始 SessionLog 的某个边界点创建新的 SessionLog，
    新日志包含原始日志的前缀事件 + 自己的新事件。
    """

    def __init__(self, source_log: SessionLog):
        self._source = source_log

    def at(self, boundary_seq: int, new_session_id: Optional[str] = None) -> SessionLog:
        """从指定 seq 边界点分叉。

        Args:
            boundary_seq: 分叉点的事件序号（包含该事件）
            new_session_id: 新会话 ID（不指定则自动生成）

        Returns:
            新的 SessionLog 实例，包含到 boundary_seq 为止的事件
        """
        new_id = new_session_id or f'fork-{uuid.uuid4().hex[:12]}'

        # 获取分叉点之前的所有事件
        events = self._source.get_events()
        fork_events = [e for e in events if e.seq <= boundary_seq]

        # 创建新日志
        new_log = SessionLog(
            session_id=new_id,
            db=self._source._db,
        )

        # 重放分叉点之前的事件
        for event in fork_events:
            new_log._events.append(SessionEvent(
                seq=event.seq,
                time=event.time,
                type=event.type,
                data=dict(event.data),
            ))
        new_log._next_seq = boundary_seq + 1

        # 记录分叉事件
        new_log.append(EventType.TURN_START, {
            'turn': 0,
            'forked_from': self._source.session_id,
            'fork_boundary_seq': boundary_seq,
        })

        logger.info(
            '会话分叉: %s → %s (boundary_seq=%d, events=%d)',
            self._source.session_id, new_id, boundary_seq, len(fork_events),
        )

        return new_log

    def resume(self, session_id: str, db=None) -> SessionLog:
        """从持久化恢复会话。

        从数据库加载已有的事件，恢复 SessionLog 状态。
        用于崩溃恢复或跨进程继续。
        """
        new_log = SessionLog(
            session_id=session_id,
            db=db or self._source._db,
        )

        # 从数据库加载事件
        events = new_log.load_from_db()
        if events:
            new_log._events = events
            new_log._next_seq = max(e.seq for e in events) + 1

        logger.info(
            '会话恢复: %s (events=%d)',
            session_id, len(new_log._events),
        )

        return new_log

    def list_fork_points(self) -> list[dict]:
        """列出可分叉的边界点（turn 边界）。

        Returns:
            [{'seq': int, 'turn': int, 'time': float}, ...]
        """
        events = self._source.get_events()
        points = []
        for e in events:
            if e.type == EventType.TURN_START:
                points.append({
                    'seq': e.seq,
                    'turn': e.data.get('turn', 0),
                    'time': e.time,
                })
        return points


class SessionResume:
    """会话恢复器 — 从持久化事件恢复。

    用于崩溃恢复场景：从 SQLite 加载已有事件，
    重建 SessionLog 并继续。
    """

    @staticmethod
    def from_db(session_id: str, db) -> SessionLog:
        """从数据库恢复 SessionLog。"""
        log = SessionLog(session_id=session_id, db=db)
        events = log.load_from_db()
        if events:
            log._events = events
            log._next_seq = max(e.seq for e in events) + 1
            logger.info('恢复会话 %s: %d 个事件', session_id, len(events))
        else:
            logger.warning('会话 %s 无历史事件', session_id)
        return log

    @staticmethod
    def list_sessions(db) -> list[dict]:
        """列出所有可恢复的会话。"""
        try:
            cursor = db._get_conn().execute(
                'SELECT DISTINCT session_id, COUNT(*) as event_count, '
                'MIN(time) as created, MAX(time) as updated '
                'FROM session_events GROUP BY session_id ORDER BY updated DESC'
            )
            return [
                {
                    'session_id': row[0],
                    'event_count': row[1],
                    'created': row[2],
                    'updated': row[3],
                }
                for row in cursor.fetchall()
            ]
        except Exception:
            logger.debug('列出会话失败', exc_info=True)
            return []
